function bindRows(){document.querySelectorAll('[data-entry-add]').forEach(el=>el.onclick=e=>{e.stopPropagation();addTask(el.dataset.entryAdd);});document.querySelectorAll('[data-percent]').forEach(el=>{el.onchange=()=>savePercent(el);el.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();el.blur();}if(e.key==='Escape'){const t=shown.tasks.find(t=>t.id===el.dataset.percent);el.value=C.progress(t);el.blur();}};});document.querySelectorAll('[data-duration]').forEach(el=>{el.onchange=()=>saveDuration(el);el.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();el.blur();}if(e.key==='Escape'){el.value=live.tasks.find(t=>t.id===el.dataset.duration).dur;el.blur();}};});document.querySelectorAll('[data-open]').forEach(el=>el.onclick=e=>{if(e.target.closest('[data-collapse],[data-entry-add]'))return;openEditor(el.dataset.open);});document.querySelectorAll('[data-collapse]').forEach(el=>el.onclick=e=>{e.stopPropagation();collapsed.has(el.dataset.collapse)?collapsed.delete(el.dataset.collapse):collapsed.add(el.dataset.collapse);render();});}
function closeEditor(force=false){if(dirty&&!force&&!confirm('Закрыть карточку без сохранения?'))return false;$('drawer').classList.remove('open');draft=null;dirty=false;return true;}
function option(id,label,current){return`<option value="${esc(id)}"${id===current?' selected':''}>${esc(label)}</option>`;}
function field(label,id,value,type='text',disabled=false){return`<div class="f"><label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value??'')}" ${disabled?'disabled':''} ${type==='number'?(id==='taskDuration'?'step="1"':'step="any"'):''}></div>`;}
function openEditor(id){if(dirty&&!confirm('Закрыть несохранённые изменения?'))return;const t=shown.tasks.find(t=>t.id===id);if(!t){error(Error('Эта работа отсутствует в выбранном состоянии.'));return;}draft=C.copy(t);dirty=false;editor();$('drawer').classList.add('open');}
function parkingParent(t){const seen=new Set;let p=shown.tasks.find(x=>x.id===t.parent);while(p&&!seen.has(p.id)){seen.add(p.id);if(p.parent==='parking-root')return p;p=shown.tasks.find(x=>x.id===p.parent);}return null;}
function parkingFields(t,ro){const parent=shown.tasks.find(x=>x.id===t.parent),section=t.section||parkingParent(t)?.name||'',zone=t.zone||(parent?.parent&&parent.parent!=='parking-root'?parent.name:'');return `<div class="sect">Расположение в паркинге</div>${field('Раздел (по родительской группе)','parkingSection',section,'text',true)}<div class="g2">${field('Захватка / зона','parkingZone',zone,'text',ro)}${field('Этаж / номер','parkingFloor',t.floor,'text',ro)}</div>${field('Ресурс / установка','parkingResource',t.resourceName,'text',ro)}<p class="drawer-note">Название работы вводите отдельно от захватки. Расположение выводится подписью под работой и попадает в печать.</p>`;}
function readParkingFields(t){if(!parkingParent(t))throw Error('Выберите раздел паркинга или группу внутри раздела.');t.section=parkingParent(t).name;t.zone=$('parkingZone').value.trim();t.floor=$('parkingFloor').value.trim();t.resourceName=$('parkingResource').value.trim();}
