function inheritEntry(t,source=null){const inherited=E.inherit(shown.tasks,t.parent,entryKeys());for(const k of entryKeys())t[k]=source?.[k]??inherited[k]??'';if(isParking()){const parent=shown.tasks.find(x=>x.id===t.parent);t.section=parkingParent(t)?.name||'';if(parent?.parent&&parent.parent!=='parking-root')t.zone=parent.name;}if(isLifts()){const chain=E.lineage(shown.tasks,t.parent);t.building=chain.find(x=>x.parent&&!shown.tasks.find(y=>y.id===x.parent)?.parent)?.building||chain.find(x=>x.building)?.building||inherited.building||'';}}
