$('scheduleSelect').onchange=async e=>{if(dirty&&!confirm('Переключить график без сохранения карточки?')){e.target.value=sid;return;}if(busy){e.target.value=sid;return;}try{location.href=await window.GPR_CUTS.scheduleUrl(client,e.target.value);}catch(e){error(e);}};
$('refresh').onclick=()=>load().catch(error);$('baselineSelect').onchange=()=>selectBase().then(render).catch(error);$('compare').onclick=()=>selectStates().catch(error);for(const id of ['reportDate','compareDate'])$(id).onchange=()=>{if(dirty&&!confirm('Закрыть несохранённые изменения?'))return;closeEditor(true);selectStates().catch(error);};
let calendarPeriodTimer;
function applyCalendarPeriod(){
 if(!calendarPeriod()){$('periodNotice').textContent='Введите обе даты полностью (год из четырёх цифр), начало не позже окончания; период до 730 дней.';return;}
 $('periodNotice').textContent='';$('lookAhead').value='';$('rowMode').disabled=false;collapsed.clear();render();
}
for(const id of ['rangeStart','rangeEnd'])$(id).onchange=()=>{clearTimeout(calendarPeriodTimer);calendarPeriodTimer=setTimeout(applyCalendarPeriod,450);};
$('periodOnly').onchange=applyCalendarPeriod;
for(const id of ['rowMode','includeOverdue','groupFilter','hideDone','showLinks'])$(id).onchange=render;$('search').oninput=render;
$('views').querySelector('[data-view="history"]').hidden=true;
$('views').querySelectorAll('button').forEach(b=>b.onclick=async()=>{if(dirty){error(Error('Сначала сохраните или закройте карточку.'));return;}view=b.dataset.view;for(const x of $('views').querySelectorAll('button'))x.classList.toggle('on',x===b);if(view==='compare'||view==='history'){historical=false;shown=C.copy(live);await cuts.activate();}else{cuts.deactivate();await selectStates().catch(error);}});$('zooms').querySelectorAll('button').forEach(b=>b.onclick=()=>{zoom=b.dataset.zoom;$('zooms').querySelectorAll('button').forEach(x=>x.classList.toggle('on',x===b));render();});$('collapse').onclick=()=>{if(cuts.active){cuts.toggleGroups();return;}if(collapsed.size)collapsed.clear();else shown?.tasks.filter(t=>t.summary&&t.parent).forEach(t=>collapsed.add(t.id));$('collapse').textContent=collapsed.size?'Развернуть группы':'Свернуть группы';render();};
$('login').onclick=()=>{$('authError').textContent='';$('authDialog').showModal();};$('authCancel').onclick=()=>{$('authDialog').close();$('password').value='';};$('authForm').onsubmit=async e=>{e.preventDefault();$('authSubmit').disabled=true;try{await response(client.auth.signInWithPassword({email:$('email').value.trim(),password:$('password').value}));$('password').value='';$('authDialog').close();await load();}catch(e){$('authError').textContent=e.message;}finally{$('authSubmit').disabled=false;}};
$('logout').onclick=async()=>{if(busy)return;if(dirty&&!confirm('Выйти без сохранения?'))return;await response(client.auth.signOut({scope:'local'}));session=null;if(isPrivate())lockPrivate();closeEditor(true);await load().catch(error);};
client.auth.onAuthStateChange?.(event=>{if(event==='SIGNED_OUT'&&isPrivate()){session=null;lockPrivate();}});
window.addEventListener('beforeunload',e=>{if(dirty||busy){e.preventDefault();e.returnValue='';}});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&draft)closeEditor();});
document.body.classList.add('compact-rows');$('compact').onchange=()=>{document.body.classList.toggle('compact-rows',$('compact').checked);scheduleLinks();};$('nameWidth').oninput=()=>{document.documentElement.style.setProperty('--name-width',$('nameWidth').value+'px');render();};$('lookAhead').onchange=()=>{$('rowMode').disabled=false;if($('lookAhead').value){collapsed.clear();$('rangeStart').value=$('reportDate').value;$('rangeEnd').value=C.date(C.time($('reportDate').value)+(+$('lookAhead').value-1)*C.DAY);}render();};
$('reportDate').value=today;$('compareDate').value=C.date(C.time(today)-7*C.DAY);$('rangeStart').value=today.slice(0,7)+'-01';$('rangeEnd').value=C.date(Date.UTC(+today.slice(0,4),+today.slice(5,7)+1,0));
