window.GPR_MOCKUP={load,printTable,getData:()=>C.copy(live),getShown:()=>shown&&C.copy(shown),getPrior:()=>prior&&C.copy(prior),openEditor,render};
if(isPrivate()){document.body.classList.add('private-locked');$('authForm').querySelector('p').textContent='График закрыт на время интеграции и тестирования. Вход доступен владельцу.';$('title').textContent=privateTitles[sid];document.title=privateTitles[sid]+' · ГПР';}
try{await load();}catch(e){error(e);$('accessStatus').textContent=isPrivate()?'Закрытый график · требуется вход':'Не удалось подключиться';if(isPrivate())$('workspace').innerHTML='<div class="m-empty">График доступен владельцу после входа. Используйте кнопку «Войти для редактирования».</div>';}
